                filter?: components["parameters"]["FilterTree"];
                /** @description 0.15.68 (W8 item 5). The search box of a site-data list. One token: contains, ignoring case, on the Site ID, the Site Owner ID and the name (and the other text columns the list names). Two or more tokens separated by spaces, new lines, tabs, commas or semicolons (cells copied from Excel): a pasted list, each token matches the Site ID or the Site Owner ID exactly, ignoring case, one row per site, duplicates ignored. At most 1000 distinct codes: 422 `validation_failed` with `too_many_codes` at `/q`. The caller's regions and row security still apply; the answer carries `search` for a list. */
                q?: components["parameters"]["SiteSearch"];
                /** @description Site IDs, comma-separated (multi Site ID search, exact match). */
                site_code?: string;
                /** @description Region numbers 1 to 7, comma-separated. */
                region_id?: string;
                sub_region?: string;
                /** @description Project phase, comma-separated. */
                phase?: string;
                /** @description Delivery batch, comma-separated. */
                batch?: string;
                scenario?: string;
                /** @description CW delivery model (outsourced or internal). */
                delivery_model?: string;
                /** @description Overall status, comma-separated. */
                status?: string;
                /** @description Current milestone, comma-separated. */
                milestone?: string;
                /** @description Contractor Name (Master AJ) of the first procurement order of scope CW, Tower Erection or Site Adaption that is neither cancelled nor rejected (0.15.33, the workbook rule), comma-separated. A caller without the procurement view matches no site. */
                contractor?: string;
                /** @description 0.15.50. The current stage (milestone code, for example MS2) of the site, as in `GET /sites`. */
                stage_code?: string;
                /** @description 0.15.50. `mine` (sites with open work held by the caller), `late` (an overdue open task), `waiting_approval`, `closed`; as in `GET /sites`. */
                bucket?: "all" | "mine" | "late" | "waiting_approval" | "closed";
                /** @description 0.15.50. `locked` keeps the sites whose sequencing locks apply, `open` the sites whose locks are off. */
                workflow_locks?: "locked" | "open";
                /** @description 0.15.50. `with` keeps the sites with at least one missing required value, `without` the others. */
                data_gaps?: "with" | "without";
